import React from "react";
import classes from "./Header.module.css";
export const Header = () => {
  return (
    <header className={classes.header}>
      <p>Коннект</p>
      <ul>
        <li>Коннект</li>
        <li>афиша</li>
        <li>обсуждения</li>
      </ul>
      <button>
        <p>войти</p>
      </button>
    </header>
  );
};
